#!/usr/bin/env python3
"""Write the Android host's MainActivity: the SAF method channel behind
folder import.

The DreamTX repo does not commit the android platform folder — it is
regenerated by `flutter create` on every CI run (which only creates
MISSING files, so a checked-in host would silently drift from what the
build actually compiles). This script runs right after `flutter create`
and REPLACES the generated template MainActivity with DreamTX's own:

  * it registers the `dreamtx/saf` method channel;
  * `list` walks one picked SAF tree URI (files in subfolders included,
    breadth-first, hard-capped) via pure DocumentsContract queries — no
    extra AndroidX dependencies needed on the classpath;
  * `copyToCache` streams one document into the app cache and returns
    the local path, which the resource store then copies into its own
    documents tree.

Dart side: app/lib/core/saf_bridge.dart. Idempotent: rewriting an
already-current host is a no-op; a changed host is rewritten wholesale.
"""
import os
import sys

MAIN_ACTIVITY = r'''package com.dreamtx.dreamtx

import android.net.Uri
import android.provider.DocumentsContract
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File

class MainActivity : FlutterActivity() {

    companion object {
        const val CHANNEL = "dreamtx/saf"
        const val MAX_FILES = 400
    }

    override fun configureFlutterEngine(engine: FlutterEngine) {
        super.configureFlutterEngine(engine)
        MethodChannel(engine.dartExecutor.binaryMessenger, CHANNEL).setMethodCallHandler { call, result ->
            try {
                when (call.method) {
                    "list" -> result.success(listTree(call.arguments as String))
                    "copyToCache" -> result.success(copyToCache(call.arguments as String))
                    else -> result.notImplemented()
                }
            } catch (e: Exception) {
                result.error("saf", e.message ?: e.javaClass.simpleName, null)
            }
        }
    }

    /**
     * Lists the files inside one picked SAF tree, subfolders included
     * (breadth-first, hard-capped so a runaway tree can never wedge the
     * import). Pure DocumentsContract queries — no extra dependencies.
     */
    private fun listTree(treeString: String): Map<String, Any> {
        val tree = Uri.parse(treeString)
        val rootId = DocumentsContract.getTreeDocumentId(tree)
        val files = mutableListOf<Map<String, Any>>()
        val dirs = ArrayDeque<String>()
        dirs.addLast(rootId)
        while (dirs.isNotEmpty() && files.size < MAX_FILES) {
            val dirId = dirs.removeFirst()
            val childrenUri =
                DocumentsContract.buildChildDocumentsUriUsingTree(tree, dirId)
            contentResolver.query(
                childrenUri,
                arrayOf(
                    DocumentsContract.Document.COLUMN_DOCUMENT_ID,
                    DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                    DocumentsContract.Document.COLUMN_MIME_TYPE,
                    DocumentsContract.Document.COLUMN_SIZE,
                ),
                null, null, null
            )?.use { cursor ->
                while (cursor.moveToNext() && files.size < MAX_FILES) {
                    val id = cursor.getString(0) ?: continue
                    val name = cursor.getString(1) ?: id
                    val mime = cursor.getString(2) ?: ""
                    val docUri = DocumentsContract.buildDocumentUriUsingTree(tree, id)
                    if (mime == DocumentsContract.Document.MIME_TYPE_DIR) {
                        dirs.addLast(id)
                    } else {
                        files.add(
                            mapOf(
                                "name" to name,
                                "uri" to docUri.toString(),
                                "size" to cursor.getLong(3),
                            )
                        )
                    }
                }
            }
        }
        return mapOf(
            "rootName" to queryDisplayName(tree, rootId),
            "files" to files,
        )
    }

    /** The picked tree's own display name — what the folder is called. */
    private fun queryDisplayName(tree: Uri, docId: String): String {
        val docUri = DocumentsContract.buildDocumentUriUsingTree(tree, docId)
        return try {
            contentResolver.query(
                docUri,
                arrayOf(DocumentsContract.Document.COLUMN_DISPLAY_NAME),
                null, null, null
            )?.use { cursor ->
                if (cursor.moveToFirst()) cursor.getString(0) ?: docId else docId
            } ?: docId
        } catch (_: Exception) {
            docId
        }
    }

    /**
     * Streams one document into the app cache and returns the local path
     * — the resource store then copies it into its own documents tree.
     */
    private fun copyToCache(uriString: String): String {
        val uri = Uri.parse(uriString)
        val target = File(
            cacheDir,
            "saf-" + System.currentTimeMillis() + "-" + uriString.hashCode()
        )
        contentResolver.openInputStream(uri)?.use { input ->
            target.outputStream().use { output -> input.copyTo(output) }
        } ?: throw IllegalStateException("unreadable document: $uriString")
        return target.absolutePath
    }
}
'''


def main() -> int:
    path = os.path.join(
        "app", "android", "app", "src", "main", "kotlin",
        "com", "dreamtx", "dreamtx", "MainActivity.kt")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.exists(path) and open(path).read() == MAIN_ACTIVITY:
        print("write_android_host: MainActivity.kt already current")
        return 0
    open(path, "w").write(MAIN_ACTIVITY)
    print("write_android_host: wrote " + path + " (SAF channel: dreamtx/saf)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
